// CISA KEV (Known Exploited Vulnerabilities) lookup. Framework-free so the main
// process, preload and renderer can all import it. The catalog is a bundled
// snapshot (src/shared/kev-index.ts, regenerated by scripts/update-kev.mjs) — no
// network at runtime. Used to flag findings whose CVE is actively exploited.
import { KEV, KEV_CATALOG_VERSION, type KevEntry } from './kev-index'

export { KEV_CATALOG_VERSION }

export interface KevInfo {
  cve: string
  name: string
  dateAdded: string
  dueDate?: string
  ransomware: boolean
}

/** Return KEV info for every input CVE that is in the catalog (empty if none). */
export function kevFor(cves?: string[]): KevInfo[] {
  if (!cves || cves.length === 0) return []
  const out: KevInfo[] = []
  for (const cve of cves) {
    const e: KevEntry | undefined = KEV[cve]
    if (e) out.push({ cve, name: e.name, dateAdded: e.dateAdded, dueDate: e.dueDate, ransomware: e.ransomware === true })
  }
  return out
}

/** True when any of the CVEs is in the KEV catalog. */
export function isKev(cves?: string[]): boolean {
  return !!cves && cves.some((c) => c in KEV)
}

export { KEV_COUNT } from './kev-index'

/** Tooltip for a KEV badge: one entry per CVE with its dates and ransomware flag. */
export function kevTooltip(kev: KevInfo[]): string {
  return 'CISA KEV (actively exploited) • ' + kev.map((k) =>
    `${k.cve}: added ${k.dateAdded}${k.dueDate ? `, due ${k.dueDate}` : ''}${k.ransomware ? ', ransomware' : ''}`
  ).join(' | ')
}

// Product index: "vendor|product" (as in the CISA feed) → CVE ids. Built once, on first use.
let byProduct: Map<string, string[]> | undefined
function productIndex(): Map<string, string[]> {
  if (!byProduct) {
    byProduct = new Map()
    for (const [cve, e] of Object.entries(KEV)) {
      const key = `${e.vendor}|${e.product}`
      byProduct.set(key, [...(byProduct.get(key) ?? []), cve])
    }
  }
  return byProduct
}

/** True when the catalog has at least one entry for this exact "vendor|product" key. */
export function kevProductKnown(key: string): boolean {
  return productIndex().has(key)
}

/** KEV info for every CVE listed under any of the given "vendor|product" keys (deduplicated). */
export function kevByProduct(keys: string[]): KevInfo[] {
  const seen = new Set<string>()
  const out: KevInfo[] = []
  for (const key of keys) {
    for (const cve of productIndex().get(key) ?? []) {
      if (seen.has(cve)) continue
      seen.add(cve)
      const e = KEV[cve]
      out.push({ cve, name: e.name, dateAdded: e.dateAdded, dueDate: e.dueDate, ransomware: e.ransomware === true })
    }
  }
  return out
}

/** Short CVE label for a table cell: up to three IDs, then a count. The full list goes in a tooltip. */
export function cveSummary(cves?: string[]): string {
  if (!cves || cves.length === 0) return '—'
  return cves.length > 3 ? `${cves.slice(0, 3).join(', ')} +${cves.length - 3}` : cves.join(', ')
}

/** Badge for a finding's KEV entries. A product-level hit is labelled as such, never as an exploited CVE. */
export function kevBadge(f: { tags?: string[]; kev?: KevInfo[] }): { text: 'KEV' | 'KEV product'; title: string } | null {
  if (!f.kev?.length) return null
  if (f.tags?.includes('kev-product')) {
    return { text: 'KEV product', title: `Product-level match, version not verified • ${kevTooltip(f.kev)}` }
  }
  return { text: 'KEV', title: kevTooltip(f.kev) }
}
